from django.shortcuts import render

def show_invoice(request, invoice_id):
    invoice = Invoice.objects.get(pk=invoice_id)
    lines = invoice.lines.order_by('position')
    return render(request, 'invoice.html', {'invoice': invoice, 'lines': lines})

def send_reminders(users, mailer):
    sent = []
    for user_index, user in enumerate(users):
        if user.email and not user.unsubscribed:
            mailer.send(user.email, 'Your booking is tomorrow')
            sent.append(user_index)
